//! Daily activity statistics: per-minute activity classes and MET minutes, the daily
//! activity target, and the conversion of the target to steps.
//! See `docs/algorithms/metrics.md`; the vectors in the tests are generated by
//! `tools/gen_public_vectors_activity.py`.
//!
//! Input is the ring's per-minute MET*10 bytes (`activity_information`, tag 0x50: five
//! bytes and a step count per event; 1 marks non-wear). [`ActInfo::statistics`] returns
//! class minutes, MET-minutes, equivalent distance, calories, daily target and the
//! [`Day`] record that [`super::activity_score`] consumes.

use super::activity_score::Day;

/// Minutes in the per-minute buffer.
pub const DAY_MIN: usize = 1440;

fn sign_extend_16(x: i64) -> i32 {
    (x as u16) as i16 as i32
}

/// Signed division by multiplication with a 32-bit magic number: the 64-bit product is shifted right
/// and 1 is added when the product is negative.
fn div_by_magic(w: u32, magic: u32, shift: u32) -> i32 {
    let p = (w as i32 as i64) * (magic as i32 as i64);
    ((p >> shift) + (p < 0) as i64) as i32
}

/// MET*10 from a stored byte: values of 128 and above hold `2*v - 128`.
pub fn met10_from_u8(v: u8) -> u32 {
    if v & 0x80 != 0 {
        (2 * v as u32).wrapping_sub(128)
    } else {
        v as u32
    }
}

/// MET*32 from a stored byte.
pub fn met32_from_u8(v: u8) -> u32 {
    let v = v as u32;
    if v & 0x80 != 0 {
        ((((v << 6).wrapping_sub(0x1ffb)) & 0xffff) * 0xcccd >> 19) + 0x19a
    } else {
        ((4 | (v << 5)) * 0x199a) >> 16
    }
}

/// Stored byte from MET*32.
pub fn met32_to_u8(x: u32) -> u32 {
    let x = x & 0xffff;
    if x <= 0x19a {
        ((x * 10 + 16) >> 5) & 0x7ff
    } else if x <= 0x4c5 {
        (((x * 5 + 0x180e) >> 5) & 0x7ff) ^ 0xffff_ff80
    } else {
        0xff
    }
}

/// Calories of one minute: zero at or below
/// 1.5 MET, else `(m - 48) * bmr / 1440 / 0.0..` in a fixed-point scale.
pub fn act_calories(v: u8, bmr: u32) -> u32 {
    let v = v as u32;
    let m = if v & 0x80 != 0 {
        ((((v << 6).wrapping_sub(0x1ffb)) & 0xffff) * 0xcccd >> 19) + 0x19a
    } else {
        let x = 4 | (v << 5);
        if x < 0x1ea {
            return 0;
        }
        (x * 0x199a) >> 16
    };
    let w = (m * 1000).wrapping_sub(0xbb80);
    let w = w.wrapping_mul(bmr).wrapping_add(0x5a00);
    (((w >> 10) as u64 * 0x05b0_5b06) >> 32) as u32
}

/// Equivalent walking meters per minute at MET*10 `x`.
pub fn met10_to_eq_meters(x: u32) -> i32 {
    let x = x & 0xffff;
    if x < 0x13 {
        return 0;
    }
    let (a, b): (u32, i32) = if x < 0x21 { (0x898, -0x9984) } else { (0x3e8, 0x12c) };
    div_by_magic(a.wrapping_mul(x).wrapping_add(b as u32), 0x1b4e_81b5, 38)
}

/// Equivalent meters per minute at `x` MET (single-precision input).
pub fn met_to_eq_meters(x: f32) -> f32 {
    let speed = if x <= f32::from_bits(0x3fe6_6666) {
        0.0
    } else {
        let x = if x >= f32::from_bits(0x4053_3333) {
            x
        } else {
            x.mul_add(f32::from_bits(0x400c_cccd), f32::from_bits(0xc07d_70a4))
        };
        x / 60.0
    };
    speed * 1000.0
}

/// (moderate, vigorous) limits in MET*32 for an age and gender code; the
/// defaults (128, 224) stay for gender codes other than 1, 2, 3.
pub fn met_limits(age: u32, gender: u32) -> (u32, u32) {
    let age_diff = if (age & 0xff) > 0x18 { age.wrapping_sub(0x19) } else { 0x19u32.wrapping_sub(age) };
    let d = (age_diff as u8) as i8 as i32 as u32;
    let male_vig = (d.wrapping_mul(0x1f_ffcd).wrapping_add(0x1ef1)) >> 5;
    let male_mod = (d.wrapping_mul(0x1f_ffec).wrapping_add(0x1081)) >> 5;
    let fem_mod = (d.wrapping_mul(0x1f_ffef).wrapping_add(0x11aa)) >> 5;
    let fem_vig = (d.wrapping_mul(0x1f_ffd6).wrapping_add(0x2224)) >> 5;
    match gender {
        1 => (male_mod & 0xffff, male_vig & 0xffff),
        2 => (fem_mod & 0xffff, fem_vig & 0xffff),
        3 => (
            (((fem_mod & 0xffff) + (male_mod & 0xffff) + 1) >> 1) & 0xffff,
            (((fem_vig & 0xffff) + (male_vig & 0xffff) + 1) >> 1) & 0xffff,
        ),
        _ => (128, 224),
    }
}

/// Activity class from `a = 2*m` and `b = 2*W` (`met_to_class`): 0 rest,
/// 1 sedentary, 2 light, 3 moderate, 4 vigorous.
pub fn met_to_class(a: u32, b: u32, moderate: u32, vigorous: u32) -> u8 {
    let (a, b) = (a & 0xffff, b & 0xffff);
    if vigorous * 10 < b || a > vigorous * 2 {
        4
    } else if !(moderate * 10 >= b && moderate * 2 >= a) {
        3
    } else if a > 0x73 || b > 0x240 {
        2
    } else if b > 0x14f {
        1
    } else {
        0
    }
}

/// Minutes from the day start to epoch second `t`, as the signed 16-bit value kept in
/// `state[0x676/0x678]`: -1 when `t` is at or before the day start or 24 h or more after.
pub fn sleep_minutes(t: i64, day_start: i64) -> i32 {
    let x = (t.max(day_start) as u32).wrapping_sub(day_start as u32);
    if x.wrapping_sub(86400) >= 0xfffe_ae81 {
        sign_extend_16((x as u64 * 0x8888_8889 >> 37) as i64)
    } else {
        -1
    }
}

const MALE: [(f32, f32); 2] = [(7.72, 4.11), (-0.05, -0.02)];
const FEMALE: [(f32, f32); 2] = [(8.52, 4.4), (-0.041, -0.017)];

fn fb(bits: u32) -> f32 {
    f32::from_bits(bits)
}

/// Daily target in equivalent meters.
/// `pct` is the readiness percent, `gender` the gender code of [`User`].
pub fn activity_target(pct: u32, age: u32, gender: u32) -> f32 {
    let age_dev = ((age & 0xff) as f64 - 25.0) as f32;
    let age_dev = age_dev.abs();
    let lane = |t: &[(f32, f32); 2]| (age_dev.mul_add(t[1].0, t[0].0), age_dev.mul_add(t[1].1, t[0].1));
    let lanes = match gender {
        1 => Some(lane(&MALE)),
        2 => Some(lane(&FEMALE)),
        3 => {
            let (m, f) = (lane(&MALE), lane(&FEMALE));
            Some(((m.0 + f.0) * 0.5, (m.1 + f.1) * 0.5))
        }
        _ => None,
    };
    let (lane_a, lane_b, lane_c) = match lanes {
        None => (0.0, 0.0, 0.0),
        Some((l0, l1)) => {
            let k = fb(0xbfe6_6666);
            let (l1_k, l0_k, l_diff) = (l1 + k, l0 + k, l0 - l1);
            (
                l1_k.mul_add(fb(0x3e8c_cccd), fb(0x3fe6_6666)),
                l_diff.mul_add(fb(0x3e4c_cccd), l1),
                l0_k.mul_add(1.25, fb(0x3fe6_6666)),
            )
        }
    };
    let sum_a = met_to_eq_meters(lane_a).mul_add(180.0, 0.0);
    let sum_b = met_to_eq_meters(lane_b).mul_add(45.0, sum_a);
    let total = met_to_eq_meters(lane_c).mul_add(5.0, sum_b);
    let p = pct & 0xffff;
    let f = p as f32;
    if p <= 0x45 {
        f / 100.0 * total
    } else if p >= 0x55 {
        ((f + f) / 100.0 + -0.5) * total
    } else {
        total
    }
}

/// Steps for a daily target of `target2` (twice the base target).
pub fn target_to_steps(target2: u32, bmr: u32, age: u32, gender: u32, weight: u32) -> u32 {
    let steps_scale = target2 as f32 * 60.0 / 5000.0;
    let kcal = steps_scale * act_calories(met32_to_u8(160) as u8, bmr) as f32;
    let x = kcal / 1000.0;
    let male = if gender == 1 { 1.0f32 } else { 0.0 };
    let other = if gender == 3 { 1.0f32 } else { 0.0 };
    let xd = x as f64;
    let (age_c, w_c, pick);
    if xd > 508.84764358745565 {
        let hi = xd > 776.8511438242949;
        let mut pick_hi = x * fb(0x40ae_90cb) + fb(0x464d_0b5b);
        let mut tmp_b = x * fb(0x4159_d1f8) + fb(0x45d3_2590);
        pick_hi = male * fb(0x448d_36f2) + pick_hi;
        tmp_b = male * fb(0x4492_b792) + tmp_b;
        pick_hi = other * fb(0x4305_f878) + pick_hi;
        let pick_lo = tmp_b + other * fb(0xc257_cd1b);
        if hi {
            age_c = fb(0x41e4_47c0);
            w_c = fb(0x4263_1479);
            pick = pick_hi;
        } else {
            age_c = fb(0x41de_ab0a);
            w_c = fb(0x4263_5fb2);
            pick = pick_lo;
        }
    } else {
        let hi = xd > 219.8440342176652;
        let mut pick_hi = x * fb(0x41a2_4587) + fb(0x4535_557a);
        let tmp_b = x * fb(0x41ba_c1d5) + fb(0x4461_db80);
        pick_hi = male * fb(0x448e_7f9d) + pick_hi;
        let tmp_c = male * fb(0x4401_cc68) + tmp_b;
        pick_hi = other * fb(0x41b5_f2c3) + pick_hi;
        let pick_lo = other * fb(0x4203_6e77) + tmp_c;
        if hi {
            age_c = fb(0x4187_9a6e);
            w_c = fb(0x422a_897a);
            pick = pick_hi;
        } else {
            age_c = fb(0x4104_80b3);
            w_c = fb(0x4193_d0ce);
            pick = pick_lo;
        }
    }
    let mut r = age_c * age as f32 + pick;
    r -= w_c * weight as f32;
    if r < 0.0 {
        r = 0.0;
    }
    let n = (((r / 500.0) as f64) + 0.5) as u32;
    n.wrapping_mul(500)
}

/// the user info record.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct User {
    pub bmr: u32,
    pub age: u32,
    /// Gender code: 2 male, 1 female, 3 other, 0 unknown. (The tables of this file label code 1
    /// "male".)
    pub gender: u32,
    pub weight_kg: u32,
    /// Percent of the base daily target, applied for 25..=200.
    pub target_mult: u32,
    /// 0 calories, 1 steps, other values behave like 0.
    pub target_type: u32,
}

/// Fields of the activity info output record that the activity statistics update writes, plus the day record.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Stats {
    /// Summed equivalent meters; the day record holds half.
    pub eq_distance: u32,
    pub non_wear: u32,
    /// Minutes in rest, sedentary, light, moderate and vigorous.
    pub classes: [u32; 5],
    pub avg_met32: u32,
    pub steps: u32,
    pub active_cal: u32,
    pub total_cal: u32,
    /// MET-minutes in sedentary, light, moderate and vigorous.
    pub met_min: [u32; 4],
    pub sit_alerts: u32,
    pub target_distance_m: u32,
    pub target_miles_x10: u32,
    pub target_type: u32,
    pub target_mult: u32,
    pub target_cal: u32,
    pub target_steps: u32,
    /// Remaining meters to the target, negative when exceeded.
    pub meters_to_target: i32,
    pub miles_to_target_x10: i32,
    pub day: Day,
}

/// One day of the activity info state record, reduced to the fields the statistics read.
#[derive(Clone, Debug)]
pub struct ActInfo {
    pub user: User,
    /// Per-minute maximum buffer.
    pub buf: [u8; DAY_MIN],
    /// `state[0xe]`: minutes `0..last` are counted.
    pub last: usize,
    pub steps: u32,
    /// `state[0xc]`, non-wear minutes held outside the buffer.
    pub non_wear_base: u32,
    pub sit_alerts: u32,
    /// `state[0x65c..0x673]`, sedentary minutes per clock hour.
    pub hourly: [u8; 24],
    cursor: usize,
    /// Stateless mode: bytes below 9 other than 1 (non-wear) count as 0.9 MET (byte 9).
    pub stateless: bool,
    /// `state[0x676]`, `state[0x678]`: last sleep period in minutes from the day start.
    pub sleep: (i32, i32),
    /// Every sleep period of the day in minutes from the day start (the stateless path rests a sedentary
    /// minute inside any of them); `None` uses `sleep` alone.
    pub ranges: Option<Vec<(i32, i32)>>,
    /// `state[0x65a]`: half of the daily target.
    pub base_target: u32,
    pub moderate_limit: u32,
    pub vigorous_limit: u32,
}

impl ActInfo {
    /// New day. With `user_met_limits` the class limits follow [`met_limits`] of the age and gender;
    /// otherwise 4.0 and 7.0 MET.
    pub fn new(user: User, user_met_limits: bool) -> Self {
        let (moderate_limit, vigorous_limit) =
            if user_met_limits { met_limits(user.age, user.gender) } else { (128, 224) };
        ActInfo {
            user,
            buf: [0; DAY_MIN],
            last: 0,
            steps: 0,
            non_wear_base: 0,
            sit_alerts: 0,
            hourly: [0; 24],
            cursor: 0,
            stateless: false,
            sleep: (0, 0),
            ranges: None,
            base_target: 0,
            moderate_limit,
            vigorous_limit,
        }
    }

    fn sleep_ranges(&self) -> Vec<(i32, i32)> {
        self.ranges.clone().unwrap_or_else(|| vec![self.sleep])
    }

    fn m32(&self, i: usize) -> u32 {
        let v = self.buf[i];
        met32_from_u8(if v == 1 { 12 } else if v < 9 && self.stateless { 9 } else { v })
    }

    /// Class per minute for minutes `0..n` before the sleep adjustment.
    pub fn classes_series(&self, n: usize) -> Vec<u8> {
        let mut out = Vec::with_capacity(n);
        let mut total: u32 = 0;
        for i in 0..n {
            let m = self.m32(i);
            total = total.wrapping_add(m);
            let w = if i >= 5 {
                total = total.wrapping_sub(self.m32(i - 5));
                total
            } else {
                let t = total & 0xffff;
                (t + t * 4) / (i as u32 + 1)
            };
            out.push(met_to_class(2 * m, w.wrapping_mul(2), self.moderate_limit, self.vigorous_limit));
        }
        out
    }

    /// Minutes `i` in `start..count` of class `cls`. A sedentary minute inside a sleep
    /// range `(s, e)` with `s < i < e` is rest. With `exclude_non_wear`, only minutes
    /// `i < last` whose byte is not 1 count.
    pub fn class_minutes(
        &self,
        cls: u8,
        start: usize,
        count: usize,
        exclude_non_wear: bool,
        ranges: &[(i32, i32)],
    ) -> u32 {
        let mut n = 0;
        for (i, &c) in self.classes_series(count).iter().enumerate() {
            let mut c = c;
            if c == 1 && ranges.iter().any(|&(s, e)| s < i as i32 && (i as i32) < e) {
                c = 0;
            }
            if i >= start && c == cls && (!exclude_non_wear || (i < self.last && self.buf[i] != 1)) {
                n += 1;
            }
        }
        n
    }

    /// Stateless variant: sleep periods as `(start_s, end_s)` epoch seconds. Leaves the last
    /// period in `self.sleep` when a sedentary minute reaches the check.
    pub fn class_minutes_periods(
        &mut self,
        cls: u8,
        start: usize,
        count: usize,
        periods: &[(i64, i64)],
        day_start: i64,
    ) -> u32 {
        let ranges: Vec<(i32, i32)> =
            periods.iter().map(|&(a, b)| (sleep_minutes(a, day_start), sleep_minutes(b, day_start))).collect();
        if let Some(&last) = ranges.last() {
            if self.classes_series(count).contains(&1) {
                self.sleep = last;
            }
        }
        self.class_minutes(cls, start, count, true, &ranges)
    }

    fn met_minutes_times32(&self, cls: u8, n: usize) -> u32 {
        let mut total = 0;
        for (i, &c) in self.classes_series(n).iter().enumerate() {
            let m = self.m32(i);
            if c == cls && m > 0x30 {
                total += m - 0x30;
            }
        }
        total
    }

    /// Copies the first
    /// `count + min(last - count, 0)` bytes of `data` to minutes `max(last - count, 0)..`
    /// with a per-minute maximum, then advances the hourly sedentary counters.
    pub fn add_activity(&mut self, last: u32, steps: u32, data: &[u8]) {
        let count = data.len() as i32;
        let in_day = (last & 0xffff) < DAY_MIN as u32;
        let end = if in_day { last as usize } else { DAY_MIN - 1 };
        let diff = sign_extend_16(last as i64 - count as i64);
        let n_len = if in_day { count } else { count - (DAY_MIN as i32 - 1 - diff).max(0) };
        let n_copy = ((n_len + diff.min(0)) & 0xffff) as usize;
        let start = diff.max(0) as usize;
        for k in 0..n_copy.min(data.len()) {
            if start + k < DAY_MIN {
                self.buf[start + k] = self.buf[start + k].max(data[k]);
            }
        }
        if end > self.last {
            self.last = end;
        }
        self.steps = (self.steps + steps).min(0xff_ffff);
        self.advance_hours();
    }

    /// Minutes `end-length..=end` become non-wear
    /// unless they already hold a value above 9.
    pub fn add_non_wear(&mut self, end: u32, length: u32) {
        let end = end & 0xffff;
        let excess = end.saturating_sub(0x59f) as i32;
        let diff = sign_extend_16(end as i64 - length as i64);
        let ln = ((length as i32 - excess + diff.min(0)) & 0xffff) as usize;
        let start = diff.max(0) as usize;
        for k in 0..=ln {
            if start + k < DAY_MIN && self.buf[start + k] <= 9 {
                self.buf[start + k] = 1;
            }
        }
        self.last = self.last.max((end as usize).min(0x59f));
        self.advance_hours();
    }

    fn advance_hours(&mut self) {
        let mut c = self.cursor;
        while c <= 0x5a0 && c != self.last {
            if c >= 60 && c % 60 == 0 {
                self.hourly[c / 60 - 1] = self.class_minutes(1, c - 60, c, true, &self.sleep_ranges()) as u8;
            }
            c += 1;
            self.cursor = c;
        }
    }

    /// Mark the day complete (`met_count` 1440): all 1440 minutes count and the hourly
    /// counters advance to the end. Minute 1439 counts only as a non-wear flag: a byte of 1 there
    /// is excluded from the class minutes, any other value acts as the minimum byte. Then the run of 0 and 1
    /// bytes at the end of the day becomes non-wear when it contains a 1; a tail of zeros is left alone.
    pub fn finish_day(&mut self, last_byte: u8) {
        if last_byte == 1 {
            self.buf[DAY_MIN - 1] = 1;
        }
        self.last = DAY_MIN;
        let mut i = DAY_MIN;
        while i > 0 && self.buf[i - 1] <= 1 {
            i -= 1;
        }
        if self.buf[i..].contains(&1) {
            for b in &mut self.buf[i..] {
                *b = 1;
            }
        }
        self.advance_hours();
    }

    /// The stateless path seeds the hourly sedentary counters from the previous day's per-minute MET
    /// bytes before the day's own data is added, when the first byte is nonzero. A scratch state with
    /// 1439 counted minutes, no sleep periods and raw bytes gives hours 0 to 22; hour 23 is 0. Hours
    /// the day has not reached keep these counts.
    pub fn seed_hourly(&mut self, prev: &[u8]) {
        if prev.first().copied().unwrap_or(0) == 0 {
            return;
        }
        self.hourly = [0; 24];
        let mut t = ActInfo::new(self.user.clone(), false);
        t.moderate_limit = self.moderate_limit;
        t.vigorous_limit = self.vigorous_limit;
        for (i, &b) in prev.iter().take(DAY_MIN).enumerate() {
            t.buf[i] = b;
        }
        t.last = 0x59f;
        t.sleep = (-1, -1);
        for c in (60..0x59f).step_by(60) {
            self.hourly[c / 60 - 1] = t.class_minutes(1, c - 60, c, true, &[t.sleep]) as u8;
        }
    }

    pub fn add_sit_alert(&mut self) {
        self.sit_alerts = (self.sit_alerts + 1) & 0xff;
    }

    /// Base target = trunc(0.5 * target). The event path
    /// substitutes 80 for a readiness percent of 0; this call does not.
    pub fn set_target(&mut self, readiness_pct: u32) {
        let t = activity_target(readiness_pct, self.user.age, self.user.gender);
        self.base_target = ((t * 0.5) as i32 as u32) & 0xffff;
    }

    /// the activity statistics update. `buf_count` is the combined-MET count field of the
    /// module buffer (0 unless the combined-MET buffer was updated).
    pub fn statistics(&self, buf_count: usize) -> Stats {
        let u = &self.user;
        let n = self.last.max(buf_count.min(0x5a0)).min(0x5a0);
        let vals: Vec<u8> = self
            .buf[..n]
            .iter()
            .map(|&b| if b == 1 { 12 } else if b < 9 && self.stateless { 9 } else { b })
            .collect();
        let mut o = Stats::default();
        o.eq_distance = vals
            .iter()
            .fold(0u32, |a, &v| a.wrapping_add(met10_to_eq_meters(met10_from_u8(v)) as u32 & 0xffff));
        o.non_wear = (self.non_wear_base + self.buf[..n].iter().filter(|&&b| b == 1).count() as u32) & 0xffff;
        for c in 0..5 {
            o.classes[c] = self.class_minutes(c as u8, 0, self.last, true, &self.sleep_ranges());
        }
        let m32: Vec<u32> = vals.iter().map(|&v| met32_from_u8(v) & 0xffff).collect();
        o.steps = self.steps;
        let bmr16 = u.bmr & 0xffff;
        if n > 0 {
            o.avg_met32 = ((m32.iter().sum::<u32>() + (n as u32 >> 1)) / n as u32) & 0xffff;
            let acc = vals
                .iter()
                .zip(&m32)
                .filter(|(_, &m)| m >= 0x31)
                .fold(0u32, |a, (&v, _)| a.wrapping_add(act_calories(v, bmr16)));
            o.active_cal = ((acc.wrapping_add(0x1f4) as u64 * 0x1062_4dd3 >> 38) & 0xffff) as u32;
        }
        let bmr_shift = bmr16 << 8;
        let mut acc = bmr_shift;
        for &m in &m32 {
            if m >= 0x23 {
                let t = (m - 0x22).wrapping_mul(bmr_shift).wrapping_add(0x5a00);
                let p = (t as i32 as i64) * (0xb60b_60b7u32 as i32 as i64);
                let w = (((p as u64) >> 32) as u32).wrapping_add(t);
                acc = acc.wrapping_add(((w as i32 >> 15) + (w >> 31) as i32) as u32);
            }
        }
        o.total_cal = (acc.wrapping_add(0x80) >> 8) & 0xffff;
        for (k, c) in [1u8, 2, 3, 4].iter().enumerate() {
            o.met_min[k] = (self.met_minutes_times32(*c, n) + 16) >> 5;
        }
        o.sit_alerts = self.sit_alerts;

        let (mult, ttype) = (u.target_mult, u.target_type);
        let mut mult_frac = 1.0f32;
        if mult.wrapping_sub(25) <= 0xaf {
            mult_frac = mult as f32 / 100.0;
        }
        let t = ((mult_frac * self.base_target as f32) as i32 as u32) & 0xffff;
        let t20 = t * 20 + 0x324;
        let t2 = t << 1;
        let steps_f = (120 * t) as f32 / 5000.0;
        let mut miles10 = ((t20 as u64 * 0x28_bb1c >> 32) as u32) + 4;
        let div_t = (miles10.wrapping_mul(0x3334)) >> 16;
        let div_t = div_t.wrapping_add(div_t << 2);
        miles10 = miles10.wrapping_sub(miles10.wrapping_sub(div_t) & 0xffff);
        o.target_distance_m = (((t2 + 0x3e7) as u64 * 0x41_8938 >> 32) as u32).wrapping_mul(1000);
        o.target_miles_x10 = miles10;
        o.target_type = ttype;
        o.target_mult = mult;
        let cal5 = act_calories(met32_to_u8(160) as u8, u.bmr);
        let v = steps_f * cal5 as f32 / 50000.0;
        let q = ((v as f64 + 0.5) as u32).wrapping_mul(50000);
        o.target_cal = (q as u64 * 0x1062_4dd3 >> 38) as u32;
        o.target_steps = target_to_steps(t2, u.bmr, u.age, u.gender, u.weight_kg);
        let flag;
        if ttype == 1 {
            let d = o.target_steps.wrapping_sub(o.steps) as i32;
            let r = (d as f32 * fb(0x3f43_126f)) as i32;
            o.meters_to_target = div_by_magic((r + 99) as u32, 0x51eb_851f, 37).wrapping_mul(100);
            o.miles_to_target_x10 = div_by_magic((r * 10 + 0x324) as u32, 0x5176_370d, 41);
            flag = if o.target_steps == 0 { 0 } else if o.target_steps > o.steps { 2 } else { 1 };
        } else {
            if u.bmr != 0 {
                let rem = o.target_cal.wrapping_sub(o.active_cal) as i32;
                let rem_scaled = rem.wrapping_mul(1000) as f32;
                let v = rem_scaled / cal5 as f32 * 5.0 * 1000.0 / 60.0;
                let r = (v as f64 + 0.5) as i32;
                o.meters_to_target = div_by_magic((r + 99) as u32, 0x51eb_851f, 37).wrapping_mul(100);
                o.miles_to_target_x10 = div_by_magic((r * 10 + 0x324) as u32, 0x5176_370d, 41);
            }
            flag = if o.target_cal == 0 { 0 } else if o.active_cal < o.target_cal { 2 } else { 1 };
        }

        let eqd = (o.eq_distance >> 1) & 0xffff;
        let m = o.meters_to_target;
        let half = (if m < -1 { m + 2 } else { m + 1 }) >> 1;
        o.day = Day {
            eq_distance: eqd as u16,
            eq_target: (half + eqd as i32).clamp(0, 0xffff) as u16,
            sedentary_min: self.hourly.iter().map(|&h| h as u32).sum::<u32>() as u16,
            moderate_met_min: o.met_min[2] as u16,
            vigorous_met_min: o.met_min[3] as u16,
            sit_alerts: (o.sit_alerts & 0xff) as u8,
            age: (u.age & 0xff) as u8,
            gender: u.gender,
            moderate_min: o.classes[3].min(0xffff) as u16,
            vigorous_min: o.classes[4].min(0xffff) as u16,
            target_reached: flag,
        };
        o
    }
}

/// Schofield coefficients (slope, intercept) per age band 1..=6; row 0 male, row 1 female.
const SCHOFIELD: [[(f64, f64); 6]; 2] = [
    [(59.512, -30.4), (22.706, 504.3), (17.686, 658.2), (15.057, 692.2), (11.472, 873.1), (11.711, 587.7)],
    [(58.317, -31.1), (20.315, 485.9), (13.384, 692.6), (14.818, 486.6), (8.126, 845.6), (9.082, 658.5)],
];
/// Band centers in half-years, indexed by the band number 1..=6 (entry 0
/// is never the upper end of a blend).
const BAND_CENTER: [i32; 7] = [0, 3, 13, 28, 48, 90, 1000];

/// Band formulas blended linearly in age between the centers of adjacent bands.
/// `sex`: 0 male, 1 female. The product and sum use one fused rounding (`mul_add`).
fn schofield(age: u32, kg: u32, sex: usize) -> f64 {
    let (age, kg) = ((age & 0xff) as i32, (kg & 0xff) as f64);
    let x = age * 2;
    let (lo, hi) = if age < 2 {
        (1, 1)
    } else {
        let hi = if x < 14 {
            2
        } else if x < 29 {
            3
        } else if x < 49 {
            4
        } else if x <= 90 {
            5
        } else {
            6
        };
        (hi - 1, hi)
    };
    let f = |band: usize| kg.mul_add(SCHOFIELD[sex][band - 1].0, SCHOFIELD[sex][band - 1].1);
    let d0 = f(lo);
    if hi <= lo {
        return d0;
    }
    let d1 = f(hi);
    d0 + (d1 - d0) * (x - BAND_CENTER[lo]) as f64 / (BAND_CENTER[hi] - BAND_CENTER[lo]) as f64
}

/// Basal metabolic rate in kcal/day (`schofield`).
/// `gender_code`: 2 male, 1 female, anything else the mean of both; the result is rounded
/// to the nearest integer. Age and weight are taken modulo 256.
/// [`super::metabolic::bmr_schofield`] calls this function; [`super::metabolic::bmr_schofield_band`]
/// is the old version without the blend between bands.
pub fn bmr(age: u32, kg: u32, gender_code: u32) -> u32 {
    let (m, f) = (schofield(age, kg, 0), schofield(age, kg, 1));
    let v = match gender_code {
        2 => m,
        1 => f,
        _ => (m + f) * 0.5,
    };
    (v + 0.5) as u32
}

#[cfg(test)]
mod tests {
    use super::*;

    fn expand(runs: &[(u8, u16)]) -> Vec<u8> {
        runs.iter().flat_map(|&(v, n)| std::iter::repeat(v).take(n as usize)).collect()
    }

    /// The vector tests, run once per vector set (`CASES`, `BMR_CASES`, `STATELESS_CASES`).
    macro_rules! vector_tests {
        () => {
    #[test]
    fn bmr_matches_reference() {
        assert!(!BMR_CASES.is_empty());
        for &(age, kg, g, want) in BMR_CASES.iter() {
            assert_eq!(bmr(age, kg, g), want, "age {age} kg {kg} gender {g}");
        }
    }

    #[test]
    fn matches_reference() {
        for (i, c) in CASES.iter().enumerate() {
            let met = expand(c.runs);
            let user = User {
                bmr: c.bmr,
                age: c.age,
                gender: c.gender,
                weight_kg: c.weight_kg,
                target_mult: c.target_mult,
                target_type: c.target_type,
            };
            let mut a = ActInfo::new(user, c.met_limits);
            a.sleep = (c.sleep.0, c.sleep.1);
            a.non_wear_base = c.non_wear_base;
            a.set_target(c.pct);
            let n = met.len();
            let chunk = if c.chunk == 0 { n } else { c.chunk as usize };
            for k in (0..n).step_by(chunk) {
                let part = &met[k..(k + chunk).min(n)];
                let last = k + part.len() - usize::from(chunk == n);
                a.add_activity(last as u32, if k == 0 { c.steps } else { 0 }, part);
            }
            for _ in 0..c.sit_alerts {
                a.add_sit_alert();
            }
            let s = a.statistics(0);
            let w = &c.words;
            let got: [u32; 24] = [
                s.eq_distance, s.non_wear, s.classes[0], s.classes[1], s.classes[2], s.classes[3], s.classes[4],
                s.avg_met32, s.steps, s.active_cal, s.total_cal, s.met_min[0], s.met_min[1], s.met_min[2],
                s.met_min[3], s.sit_alerts, s.target_distance_m, s.target_miles_x10, s.target_type, s.target_mult,
                s.target_cal, s.target_steps, s.meters_to_target as u32, s.miles_to_target_x10 as u32,
            ];
            assert_eq!(got, *w, "case {i} output words");
            assert_eq!(s.day, c.day, "case {i} day record");
            assert_eq!(a.hourly, c.hourly, "case {i} hourly counters");
        }
    }

    #[test]
    fn stateless_day_matches_reference() {
        for (i, c) in STATELESS_CASES.iter().enumerate() {
            let cur = expand(c.cur);
            let user = User { bmr: c.bmr, age: c.age, gender: c.gender, weight_kg: c.weight_kg, target_mult: 100, target_type: 0 };
            let mut a = ActInfo::new(user, true);
            a.stateless = true;
            a.seed_hourly(&expand(c.prev));
            a.set_target(c.readiness);
            let n = cur.len().min(1439);
            a.add_activity(n as u32, 0, &cur[..n]);
            if c.completed {
                a.finish_day(cur[DAY_MIN - 1]);
            }
            let s = a.statistics(0);
            assert_eq!(a.hourly, c.hourly, "case {i} hourly counters");
            assert_eq!(s.classes, c.classes, "case {i} class minutes");
        }
    }
        };
    }

    mod python_port {
        use super::*;
        include!("vectors/actinfo.rs");
        include!("vectors/actinfo_bmr.rs");
        include!("vectors/actinfo_stateless.rs");
        vector_tests!();
    }


    #[test]
    fn sedentary_day_leaves_the_last_hour_out() {
        let mut a = ActInfo::new(
            User { bmr: 1700, age: 35, gender: 1, weight_kg: 75, target_mult: 100, target_type: 0 },
            false,
        );
        a.add_activity(1439, 0, &[15; 1439]);
        assert_eq!(a.statistics(0).day.sedentary_min, 1380);
    }

    #[test]
    fn periods_make_sedentary_minutes_rest() {
        let mut a = ActInfo::new(
            User { bmr: 1700, age: 35, gender: 1, weight_kg: 75, target_mult: 100, target_type: 0 },
            false,
        );
        a.add_activity(600, 0, &[15; 600]);
        let day = 1_700_000_000;
        // sleep from minute 100 to minute 200: minutes 101..=199 turn into rest.
        let rest = a.class_minutes_periods(0, 0, 599, &[(day + 6000, day + 12000)], day);
        assert_eq!(rest, 99);
        assert_eq!(a.sleep, (100, 200));
    }
}
